// Load scenario definitions from workflow static data
const sd = getWorkflowStaticData('global');

// Initialize scenarios if not present
sd.scenarios = sd.scenarios || {
  "winter_emergency_surge": {
    "description": "Cold snap causes HVAC failures",
    "event_count": 50,
    "time_spread_minutes": 120,
    "event_distribution": {
      "emergency": 0.60,
      "inquiry": 0.25,
      "appointment": 0.10,
      "complaint": 0.05
    },
    "urgency_bias": "high",
    "time_pattern": "evening_heavy",
    "customer_pool": [1, 2, 3, 4],
    "revenue_range": [250, 600]
  },
  "routine_maintenance_day": {
    "description": "Normal business day",
    "event_count": 30,
    "time_spread_minutes": 480,
    "event_distribution": {
      "appointment": 0.50,
      "inquiry": 0.25,
      "follow_up": 0.15,
      "maintenance": 0.10
    },
    "urgency_bias": "low",
    "time_pattern": "business_hours",
    "customer_pool": [1, 2, 3, 4, 5],
    "revenue_range": [150, 350]
  },
  "summer_heatwave": {
    "description": "AC failures during heat emergency",
    "event_count": 75,
    "time_spread_minutes": 180,
    "event_distribution": {
      "emergency": 0.70,
      "inquiry": 0.20,
      "complaint": 0.10
    },
    "urgency_bias": "extreme",
    "time_pattern": "afternoon_spike",
    "customer_pool": [1, 2, 5],
    "revenue_range": [300, 800]
  }
};

// Get requested scenario or default
const scenarioName = $input.item.json.scenario_name || 'routine_maintenance_day';
const scenario = sd.scenarios[scenarioName];

if (!scenario) {
  throw new Error(`Unknown scenario: ${scenarioName}. Available: ${Object.keys(sd.scenarios).join(', ')}`);
}

// Allow overrides from webhook
const eventCount = $input.item.json.event_count || scenario.event_count;
const timeSpread = $input.item.json.time_spread_minutes || scenario.time_spread_minutes;

// Global policy settings
sd.policy = sd.policy || {
  max_events_per_run: 200,
  max_duration_seconds: 120,
  idempotency_ttl_seconds: 300,
  enable_jitter: true,
  jitter_minutes: 5
};

return {
  scenario_name: scenarioName,
  scenario: {
    ...scenario,
    event_count: eventCount,
    time_spread_minutes: timeSpread
  },
  policy: sd.policy,
  timestamp: new Date().toISOString()
};

// Generate unique run ID (ULID-style)
function generateRunId() {
  const timestamp = Date.now().toString(36).toUpperCase();
  const random = Math.random().toString(36).substring(2, 10).toUpperCase();
  return `GEN-${timestamp}-${random}`;
}

// Generate workflow sequence ID (UUID v4)
function generateUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const scenario = $input.item.json.scenario;
const scenarioName = $input.item.json.scenario_name;
const policy = $input.item.json.policy;

// Initialize idempotency cache
const sd = getWorkflowStaticData('global');
sd._event_cache = sd._event_cache || {};

// Clean expired cache entries
const now = Date.now();
for (const key in sd._event_cache) {
  if (sd._event_cache[key].expires_at < now) {
    delete sd._event_cache[key];
  }
}

// Initialize state
const state = {
  run_id: generateRunId(),
  workflow_sequence_id: generateUUID(),
  scenario_name: scenarioName,
  goal: `Generate ${scenario.event_count} events for ${scenarioName}`,
  constraints: {
    max_events: scenario.event_count,
    time_spread_minutes: scenario.time_spread_minutes,
    respect_patterns: true
  },
  counters: {
    events_created: 0,
    events_deduped: 0,
    errors: 0,
    current_step: 0,
    start_time: Date.now()
  },
  scratchpad: {
    plan: `Create ${scenario.event_count} events following ${scenario.time_pattern} pattern`,
    progress: "Initializing...",
    observations: []
  },
  scenario: scenario,
  policy: policy
};

return state;

// Pure JSON Contract - Generator Logic
const state = $input.item.json;
const scenario = state.scenario;
const eventTypes = Object.keys(scenario.event_distribution);

// Select random event type based on distribution
function selectEventType(distribution) {
  const rand = Math.random();
  let cumulative = 0;
  for (const [type, prob] of Object.entries(distribution)) {
    cumulative += prob;
    if (rand <= cumulative) return type;
  }
  return eventTypes[0];
}

// Generate urgency based on bias
function generateUrgency(bias) {
  if (bias === 'extreme') return Math.floor(Math.random() * 2) + 9; // 9-10
  if (bias === 'high') return Math.floor(Math.random() * 3) + 7; // 7-9
  if (bias === 'medium') return Math.floor(Math.random() * 4) + 4; // 4-7
  return Math.floor(Math.random() * 4) + 1; // 1-4 (low)
}

// Generate timestamp based on time pattern
function generateTimestamp(pattern, spreadMinutes) {
  const now = new Date();
  const maxOffset = spreadMinutes * 60 * 1000;

  if (pattern === 'evening_heavy') {
    // Bias toward 5PM-9PM
    const hour = Math.random() < 0.7 ? (17 + Math.floor(Math.random() * 4)) : Math.floor(Math.random() * 24);
    now.setHours(hour);
  } else if (pattern === 'afternoon_spike') {
    // Bias toward 2PM-6PM
    const hour = Math.random() < 0.7 ? (14 + Math.floor(Math.random() * 4)) : Math.floor(Math.random() * 24);
    now.setHours(hour);
  } else if (pattern === 'business_hours') {
    // 8AM-5PM
    const hour = 8 + Math.floor(Math.random() * 9);
    now.setHours(hour);
  }

  const offset = Math.floor(Math.random() * maxOffset);
  return new Date(now.getTime() - offset).toISOString();
}

// Select random customer
function selectCustomer(pool) {
  return pool[Math.floor(Math.random() * pool.length)];
}

// Generate revenue
function generateRevenue(range) {
  const [min, max] = range;
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

// Generate descriptions
const descriptions = {
  emergency: [
    "No heat - furnace completely out",
    "AC not working during heatwave",
    "Strange burning smell from HVAC",
    "Unit making loud grinding noise",
    "Thermostat showing error code"
  ],
  inquiry: [
    "Request quote for new system",
    "Question about maintenance plan",
    "Asking about energy efficiency",
    "Interest in smart thermostat",
    "General service inquiry"
  ],
  appointment: [
    "Scheduled maintenance check",
    "Follow-up from last service",
    "Annual system inspection",
    "Filter replacement appointment",
    "Routine cleaning scheduled"
  ],
  complaint: [
    "Dissatisfied with last service",
    "Billing dispute",
    "Tech arrived late",
    "Issue not fully resolved",
    "Poor communication"
  ],
  follow_up: [
    "Checking on previous repair",
    "Issue has returned",
    "Additional questions after service",
    "Requesting warranty work",
    "System still having problems"
  ],
  maintenance: [
    "Routine maintenance visit",
    "Seasonal tune-up",
    "Preventive maintenance",
    "System checkup",
    "Regular service call"
  ]
};

function selectDescription(eventType) {
  const options = descriptions[eventType] || ["General HVAC service request"];
  return options[Math.floor(Math.random() * options.length)];
}

// Generate next event
const eventType = selectEventType(scenario.event_distribution);
const urgency = generateUrgency(scenario.urgency_bias);
const customerId = selectCustomer(scenario.customer_pool);
const revenue = generateRevenue(scenario.revenue_range);
const timestamp = generateTimestamp(scenario.time_pattern, scenario.time_spread_minutes);
const description = selectDescription(eventType);

// Build output with next action
const output = {
  state: state,
  next_action: {
    action: "create_event",
    event_data: {
      event_type: eventType,
      event_timestamp: timestamp,
      customer_id: customerId,
      urgency: urgency,
      description: description,
      estimated_revenue: revenue,
      event_payload: {
        generated_by: "event_generator",
        run_id: state.run_id,
        step: state.counters.current_step + 1
      },
      is_manual_trigger: false,
      scenario_name: state.scenario_name
    }
  },
  state_update: {
    confidence: 1.0,
    reasoning: `Generated ${eventType} event for customer ${customerId}`
  }
};

return output;

// Validate generated event data
const output = $input.item.json;
const eventData = output.next_action.event_data;

// Required fields validation
const required = ['event_type', 'customer_id', 'urgency', 'description'];
for (const field of required) {
  if (!eventData[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Urgency range validation
if (eventData.urgency < 1 || eventData.urgency > 10) {
  throw new Error(`Invalid urgency: ${eventData.urgency} (must be 1-10)`);
}

// Revenue validation
if (eventData.estimated_revenue && eventData.estimated_revenue < 0) {
  throw new Error(`Invalid revenue: ${eventData.estimated_revenue}`);
}

return output;

// Idempotency gate - prevent duplicate event creation
const output = $input.item.json;
const eventData = output.next_action.event_data;
const state = output.state;
const sd = getWorkflowStaticData('global');

// Generate idempotency key
const idempotencyKey = `${state.run_id}_${eventData.event_type}_${eventData.customer_id}_${eventData.event_timestamp}`;

// Check cache
const cached = sd._event_cache[idempotencyKey];
const now = Date.now();
const ttlMs = state.policy.idempotency_ttl_seconds * 1000;

if (cached && cached.expires_at > now && cached.event_id) {
  // Cache hit - return deduped
  return {
    ...output,
    deduped: true,
    idempotency_key: idempotencyKey,
    cached_event_id: cached.event_id,
    cache_hit_at: new Date().toISOString()
  };
}

// Mark as in-flight
sd._event_cache[idempotencyKey] = {
  created_at: now,
  expires_at: now + ttlMs,
  event_id: null // Will be filled by logger
};

return {
  ...output,
  deduped: false,
  idempotency_key: idempotencyKey,
  cache_miss_at: new Date().toISOString()
};

// Log cache hit for observability
const item = $input.item.json;

return {
  run_id: item.state.run_id,
  workflow_sequence_id: item.state.workflow_sequence_id,
  action: "cache_hit",
  idempotency_key: item.idempotency_key,
  cached_event_id: item.cached_event_id,
  scenario_name: item.state.scenario_name,
  event_type: item.next_action.event_data.event_type,
  timestamp: new Date().toISOString(),
  message: "Event creation skipped (idempotency cache hit)"
};

// Update state after successful event creation
const output = $input.all()[0].json; // Get original output
const eventId = $('PostgreSQL Insert Event').first().json.event_id;
const deduped = output.deduped || false;

// Clone state
const state = JSON.parse(JSON.stringify(output.state));

// Update counters
state.counters.current_step += 1;

if (deduped) {
  state.counters.events_deduped += 1;
} else {
  state.counters.events_created += 1;

  // Update idempotency cache with event_id
  const sd = getWorkflowStaticData('global');
  if (sd._event_cache && sd._event_cache[output.idempotency_key]) {
    sd._event_cache[output.idempotency_key].event_id = eventId;
  }
}

// Update scratchpad
const created = state.counters.events_created;
const total = state.scenario.event_count;
const pct = Math.round((created / total) * 100);

state.scratchpad.progress = `Created ${created}/${total} events (${pct}%)`;
state.scratchpad.observations.push(
  deduped ? 
    `Step ${state.counters.current_step}: Deduped ${output.next_action.event_data.event_type}` :
    `Step ${state.counters.current_step}: Created ${output.next_action.event_data.event_type} (ID: ${eventId})`
);

// Keep only last 5 observations
if (state.scratchpad.observations.length > 5) {
  state.scratchpad.observations = state.scratchpad.observations.slice(-5);
}

return state;

// Format final success response
const state = $input.item.json;

const durationMs = Date.now() - state.counters.start_time;
const durationSec = (durationMs / 1000).toFixed(2);

return {
  status: "success",
  run_id: state.run_id,
  workflow_sequence_id: state.workflow_sequence_id,
  scenario_name: state.scenario_name,
  summary: {
    events_created: state.counters.events_created,
    events_deduped: state.counters.events_deduped,
    total_steps: state.counters.current_step,
    errors: state.counters.errors,
    duration_seconds: parseFloat(durationSec),
    events_per_second: (state.counters.events_created / parseFloat(durationSec)).toFixed(2)
  },
  scenario: {
    description: state.scenario.description,
    event_count: state.scenario.event_count,
    time_spread_minutes: state.scenario.time_spread_minutes,
    pattern: state.scenario.time_pattern
  },
  observations: state.scratchpad.observations,
  message: `Successfully generated ${state.counters.events_created} events in ${durationSec}s`,
  timestamp: new Date().toISOString()
};
